"""Stage 1. Render a list of notes as JSON text."""
import json


def to_json(notes):
    return json.dumps(notes, indent=2)

"""Stage 3. Write notes to a markdown file."""


def export_markdown(notes, path):
    with open(path, "w") as fh:
        for note in notes:
            fh.write("- " + note["text"] + "\n")
    return len(notes)

